<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import type { Activity, Project, ProjectPermissions, Task } from '@/Types/models';
import InputError from '@/Components/InputError.vue';
import LoadingSpinner from '@/Components/LoadingSpinner.vue';
import SubmitButton from '@/Components/SubmitButton.vue';
import { projectRepository } from '@/Repositories/projectRepository';
import { taskRepository } from '@/Repositories/taskRepository';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

const props = withDefaults(defineProps<{
    project: Project; tasks?: Task[]; activities?: Activity[]; permissions?: ProjectPermissions;
}>(), {
    tasks: () => [], activities: () => [],
    permissions: () => ({ editProject: false, deleteProject: false, editTasks: false }),
});
const statuses = [
    { key: 'todo', label: 'To do', color: 'border-slate-300', dot: 'bg-slate-400' },
    { key: 'in_progress', label: 'In progress', color: 'border-amber-300', dot: 'bg-amber-400' },
    { key: 'done', label: 'Done', color: 'border-emerald-300', dot: 'bg-emerald-500' },
];
const taskForm = useForm({ title: '', description: '', status: 'todo', priority: 'medium', assignee_id: null, due_date: '' });
const memberForm = useForm({ email: '', role: 'member' });
const createMemberForm = useForm({ name: '', email: '', role: 'member', password: '', password_confirmation: '' });
const editForm = useForm({ title: '', description: '', status: 'todo', priority: 'medium', assignee_id: null, due_date: '' });
const projectForm = useForm({ name: props.project.name, key: props.project.key, description: props.project.description || '' });
const selected = ref<Task | null>(null);
const movingTask = ref<string | null>(null);
const removingMember = ref<number | null>(null);
const deletingTask = ref(false);
const showSettings = ref(false);
const showDeleteProject = ref(false);
const showCreateMember = ref(false);
const groupedTasks = computed(() => Object.fromEntries(statuses.map(({ key }) => [key, props.tasks.filter((task) => task.status === key)])));
const taskMembers = computed(() => props.project.members || []);
const completion = computed(() => props.tasks.length ? Math.round((groupedTasks.value.done.length / props.tasks.length) * 100) : 0);

const createTask = () => taskRepository.create(taskForm, props.project.id, { preserveScroll: true, onSuccess: () => taskForm.reset('title', 'description', 'due_date') });
const addMember = () => projectRepository.addMember(memberForm, props.project.id, {
    preserveScroll: true,
    onSuccess: () => memberForm.reset('email'),
    onError: (errors) => {
        if (errors.email === 'No WorkBoard account exists with this email.') {
            createMemberForm.reset();
            createMemberForm.email = memberForm.email;
            createMemberForm.role = memberForm.role;
            showCreateMember.value = true;
        }
    },
});
const createMember = () => projectRepository.createMember(createMemberForm, props.project.id, {
    preserveScroll: true,
    onSuccess: () => { showCreateMember.value = false; memberForm.reset(); createMemberForm.reset(); },
});
const saveProject = () => projectRepository.update(projectForm, props.project.id, { preserveScroll: true, onSuccess: () => { showSettings.value = false; } });
const deleteProject = () => projectRepository.delete(projectForm, props.project.id);
const openTask = (task) => { selected.value = task; editForm.defaults({ title: task.title, description: task.description || '', status: task.status, priority: task.priority, assignee_id: task.assignee?.id || null, due_date: task.due_date || '' }); editForm.reset(); };
const saveTask = () => taskRepository.update(editForm, selected.value.id, { preserveScroll: true, onSuccess: () => { selected.value = null; } });
const moveTask = (task, status) => {
    const operation = task.id + ':' + status; movingTask.value = operation;
    taskRepository.move(task.id, { status, position: task.position }, { preserveScroll: true, onFinish: () => { movingTask.value = null; } });
};
const removeMember = (member) => { removingMember.value = member.id; projectRepository.removeMember(props.project.id, member.id, { preserveScroll: true, onFinish: () => { removingMember.value = null; } }); };
const deleteTask = () => { deletingTask.value = true; taskRepository.delete(selected.value.id, { preserveScroll: true, onSuccess: () => { selected.value = null; }, onFinish: () => { deletingTask.value = false; } }); };
const formatDate = (value) => value ? new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value + (value.length === 10 ? 'T00:00:00' : ''))) : 'No due date';
</script>

<template>
    <Head :title="project.name" />
    <AuthenticatedLayout>
        <template #header><div class="flex flex-wrap items-center justify-between gap-4"><div><Link :href="route('projects.index')" class="text-sm font-semibold text-indigo-600 hover:text-indigo-800">← All projects</Link><div class="mt-1 flex items-center gap-3"><h2 class="text-xl font-bold text-slate-900">{{ project.name }}</h2><span class="rounded-md bg-indigo-50 px-2 py-1 text-xs font-bold text-indigo-700">{{ project.key }}</span></div></div><button v-if="permissions.editProject" type="button" class="rounded-xl border border-slate-200 bg-white px-3.5 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-50" @click="showSettings = true">Project settings</button></div></template>

        <div class="mx-auto max-w-[1500px] space-y-6 px-4 py-7 sm:px-6 lg:px-8">
            <section class="grid gap-4 lg:grid-cols-[1fr_auto]">
                <div class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-sm leading-6 text-slate-600">{{ project.description || 'No description has been added to this project yet.' }}</p><div class="mt-4 flex flex-wrap items-center gap-2"><span v-for="member in project.members" :key="member.id" class="inline-flex items-center gap-2 rounded-full bg-slate-100 py-1 pl-1 pr-3 text-xs font-medium text-slate-600"><span class="grid h-6 w-6 place-items-center rounded-full bg-indigo-100 font-bold text-indigo-700">{{ member.name.charAt(0).toUpperCase() }}</span>{{ member.name }}<span class="text-slate-400">· {{ member.role }}</span></span></div></div>
                <div class="flex items-center gap-5 rounded-2xl border border-slate-200 bg-white px-6 py-4 shadow-sm"><div><p class="text-xs font-medium text-slate-400">Progress</p><p class="mt-1 text-2xl font-bold text-slate-900">{{ completion }}%</p></div><div class="h-14 w-px bg-slate-100"></div><div><p class="text-xs font-medium text-slate-400">Tasks</p><p class="mt-1 text-2xl font-bold text-slate-900">{{ tasks.length }}</p></div></div>
            </section>

            <section v-if="permissions.editTasks" class="grid gap-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm lg:grid-cols-2 lg:p-6">
                <form class="grid gap-3" @submit.prevent="createTask"><div><h3 class="font-bold text-slate-900">Add task</h3><p class="text-xs text-slate-400">Create a new item for this board.</p></div><input v-model="taskForm.title" required maxlength="180" class="rounded-xl border-slate-300 text-sm focus:border-indigo-500 focus:ring-indigo-500" placeholder="What needs to be done?" /><InputError :message="taskForm.errors.title" /><textarea v-model="taskForm.description" maxlength="5000" class="rounded-xl border-slate-300 text-sm focus:border-indigo-500 focus:ring-indigo-500" rows="2" placeholder="Description (optional)" /><div class="grid gap-2 sm:grid-cols-3"><select v-model="taskForm.priority" class="rounded-xl border-slate-300 text-sm"><option value="low">Low priority</option><option value="medium">Medium priority</option><option value="high">High priority</option></select><select v-model="taskForm.assignee_id" class="rounded-xl border-slate-300 text-sm"><option :value="null">Unassigned</option><option v-for="member in taskMembers" :key="member.id" :value="member.id">{{ member.name }}</option></select><input v-model="taskForm.due_date" class="rounded-xl border-slate-300 text-sm" type="date" /></div><InputError :message="taskForm.errors.assignee_id" /><SubmitButton class="w-fit" :loading="taskForm.processing" loading-text="Adding…">Add task</SubmitButton></form>
                <form v-if="permissions.editProject" class="grid content-start gap-3 border-t border-slate-100 pt-5 lg:border-l lg:border-t-0 lg:pl-6 lg:pt-0" @submit.prevent="addMember"><div><h3 class="font-bold text-slate-900">Add team member</h3><p class="text-xs text-slate-400">Existing users are added directly. For a new email, we’ll help you create an account.</p></div><div class="flex flex-col gap-2 sm:flex-row"><input v-model="memberForm.email" required class="min-w-0 flex-1 rounded-xl border-slate-300 text-sm" placeholder="person@example.com" type="email" /><select v-model="memberForm.role" class="rounded-xl border-slate-300 text-sm"><option value="member">Member</option><option value="viewer">Viewer</option></select><SubmitButton variant="outline" :loading="memberForm.processing" loading-text="Checking…">Add</SubmitButton></div><InputError v-if="memberForm.errors.email !== 'No WorkBoard account exists with this email.'" :message="memberForm.errors.email" /></form>
            </section>

            <section class="grid gap-5 xl:grid-cols-3">
                <div v-for="status in statuses" :key="status.key" class="min-w-0 rounded-2xl border-t-4 bg-slate-100/80 p-3" :class="status.color"><div class="mb-3 flex items-center justify-between px-1"><div class="flex items-center gap-2"><span class="h-2 w-2 rounded-full" :class="status.dot"></span><h3 class="font-bold text-slate-700">{{ status.label }}</h3></div><span class="rounded-full bg-white px-2 py-0.5 text-xs font-semibold text-slate-500">{{ groupedTasks[status.key].length }}</span></div>
                    <div class="space-y-3"><article v-for="task in groupedTasks[status.key]" :key="task.id" class="cursor-pointer rounded-xl bg-white p-4 shadow-sm ring-1 ring-slate-200 transition hover:-translate-y-0.5 hover:ring-indigo-300 hover:shadow-md" @click="openTask(task)"><div class="flex items-start justify-between gap-3"><h4 class="font-semibold leading-5 text-slate-800">{{ task.title }}</h4><span class="shrink-0 rounded-md px-2 py-0.5 text-[11px] font-bold capitalize" :class="{ 'bg-rose-50 text-rose-700': task.priority === 'high', 'bg-amber-50 text-amber-700': task.priority === 'medium', 'bg-slate-100 text-slate-600': task.priority === 'low' }">{{ task.priority }}</span></div><p v-if="task.description" class="mt-2 line-clamp-2 text-sm leading-5 text-slate-500">{{ task.description }}</p><div class="mt-4 flex items-center justify-between gap-2 text-xs text-slate-400"><span class="truncate">{{ task.assignee?.name || 'Unassigned' }}</span><time class="shrink-0" :class="task.due_date && task.status !== 'done' && new Date(task.due_date + 'T23:59:59') < new Date() ? 'font-semibold text-rose-600' : ''">{{ formatDate(task.due_date) }}</time></div><div v-if="permissions.editTasks" class="mt-3 flex flex-wrap gap-1 border-t border-slate-100 pt-3" @click.stop><button v-for="move in statuses.filter((item) => item.key !== task.status)" :key="move.key" type="button" :disabled="movingTask !== null" class="inline-flex items-center gap-1 rounded-lg border border-slate-200 px-2 py-1 text-[11px] font-medium text-slate-500 hover:bg-slate-50 disabled:opacity-50" @click="moveTask(task, move.key)"><LoadingSpinner v-if="movingTask === task.id + ':' + move.key" size="xs" label="Moving task" />{{ movingTask === task.id + ':' + move.key ? 'Moving…' : 'Move to ' + move.label }}</button></div></article><div v-if="!groupedTasks[status.key].length" class="rounded-xl border border-dashed border-slate-300 px-3 py-10 text-center"><p class="text-sm font-medium text-slate-400">No tasks here</p></div></div>
                </div>
            </section>

            <section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h3 class="font-bold text-slate-900">Recent activity</h3><div v-if="activities.length" class="mt-4 divide-y divide-slate-100"><div v-for="activity in activities" :key="activity.id" class="flex items-center justify-between gap-4 py-3 text-sm"><p class="text-slate-500"><span class="font-semibold text-slate-700">{{ activity.actor?.name || 'System' }}</span> {{ activity.action }} a task</p><time class="shrink-0 text-xs text-slate-400">{{ new Date(activity.created_at).toLocaleDateString() }}</time></div></div><p v-else class="mt-4 text-sm text-slate-500">Activity will appear when tasks change.</p></section>
        </div>

        <div v-if="selected" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4 backdrop-blur-sm" @click.self="selected = null"><form class="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl" @submit.prevent="saveTask"><div class="flex items-center justify-between"><div><p class="text-xs font-bold uppercase tracking-wider text-indigo-600">{{ project.key }} task</p><h3 class="mt-1 text-lg font-bold text-slate-900">Task details</h3></div><button type="button" class="grid h-9 w-9 place-items-center rounded-lg text-slate-400 hover:bg-slate-100" @click="selected = null">✕</button></div><div class="mt-6 space-y-4"><label class="grid gap-1.5 text-sm font-semibold text-slate-700">Title<input v-model="editForm.title" :disabled="!permissions.editTasks" required class="rounded-xl border-slate-300 disabled:bg-slate-50" /></label><InputError :message="editForm.errors.title" /><label class="grid gap-1.5 text-sm font-semibold text-slate-700">Description<textarea v-model="editForm.description" :disabled="!permissions.editTasks" class="rounded-xl border-slate-300 disabled:bg-slate-50" rows="4" /></label><div class="grid gap-3 sm:grid-cols-2"><label class="grid gap-1.5 text-sm font-semibold">Status<select v-model="editForm.status" :disabled="!permissions.editTasks" class="rounded-xl border-slate-300 disabled:bg-slate-50"><option v-for="status in statuses" :key="status.key" :value="status.key">{{ status.label }}</option></select></label><label class="grid gap-1.5 text-sm font-semibold">Priority<select v-model="editForm.priority" :disabled="!permissions.editTasks" class="rounded-xl border-slate-300 disabled:bg-slate-50"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></label><label class="grid gap-1.5 text-sm font-semibold">Assignee<select v-model="editForm.assignee_id" :disabled="!permissions.editTasks" class="rounded-xl border-slate-300 disabled:bg-slate-50"><option :value="null">Unassigned</option><option v-for="member in taskMembers" :key="member.id" :value="member.id">{{ member.name }}</option></select></label><label class="grid gap-1.5 text-sm font-semibold">Due date<input v-model="editForm.due_date" :disabled="!permissions.editTasks" class="rounded-xl border-slate-300 disabled:bg-slate-50" type="date" /></label></div><InputError :message="editForm.errors.assignee_id" /></div><div class="mt-6 flex items-center justify-between gap-3"><button v-if="permissions.deleteProject" type="button" :disabled="deletingTask" class="inline-flex items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold text-rose-600 hover:bg-rose-50 disabled:opacity-50" @click="deleteTask"><LoadingSpinner v-if="deletingTask" label="Deleting task" />{{ deletingTask ? 'Deleting…' : 'Delete task' }}</button><div class="ml-auto flex gap-2"><button type="button" :disabled="editForm.processing" class="rounded-lg px-4 py-2 text-sm font-semibold text-slate-500 hover:bg-slate-100" @click="selected = null">Close</button><SubmitButton v-if="permissions.editTasks" :loading="editForm.processing" loading-text="Saving…">Save changes</SubmitButton></div></div></form></div>

        <div v-if="showCreateMember" class="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-sm" @click.self="showCreateMember = false"><form class="max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl" @submit.prevent="createMember"><div class="flex items-start justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-wider text-indigo-600">New WorkBoard account</p><h3 class="mt-1 text-xl font-bold text-slate-900">Create and add member</h3><p class="mt-2 text-sm leading-6 text-slate-500">No user exists with <strong>{{ createMemberForm.email }}</strong>. Create one now and share the temporary password securely.</p></div><button type="button" class="grid h-9 w-9 shrink-0 place-items-center rounded-lg text-slate-400 hover:bg-slate-100" @click="showCreateMember = false">✕</button></div><div class="mt-6 space-y-4"><label class="grid gap-1.5 text-sm font-semibold text-slate-700">Full name<input v-model="createMemberForm.name" required autofocus maxlength="120" class="h-11 rounded-xl border-slate-300 text-sm" placeholder="Member name" /></label><InputError :message="createMemberForm.errors.name" /><label class="grid gap-1.5 text-sm font-semibold text-slate-700">Email address<input v-model="createMemberForm.email" required type="email" class="h-11 rounded-xl border-slate-300 bg-slate-50 text-sm" /></label><InputError :message="createMemberForm.errors.email" /><label class="grid gap-1.5 text-sm font-semibold text-slate-700">Project role<select v-model="createMemberForm.role" class="h-11 rounded-xl border-slate-300 text-sm"><option value="member">Member — can manage tasks</option><option value="viewer">Viewer — read only</option></select></label><div class="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs leading-5 text-amber-800">This is a temporary password. On first login, the member must replace it before accessing the dashboard.</div><label class="grid gap-1.5 text-sm font-semibold text-slate-700">Temporary password<input v-model="createMemberForm.password" required minlength="8" type="password" autocomplete="new-password" class="h-11 rounded-xl border-slate-300 text-sm" placeholder="Minimum 8 characters" /></label><InputError :message="createMemberForm.errors.password" /><label class="grid gap-1.5 text-sm font-semibold text-slate-700">Confirm temporary password<input v-model="createMemberForm.password_confirmation" required type="password" autocomplete="new-password" class="h-11 rounded-xl border-slate-300 text-sm" /></label></div><div class="mt-6 flex justify-end gap-2"><button type="button" class="rounded-lg px-4 py-2 text-sm font-semibold text-slate-500 hover:bg-slate-100" @click="showCreateMember = false">Cancel</button><SubmitButton :loading="createMemberForm.processing" loading-text="Creating…">Create member</SubmitButton></div></form></div>

        <div v-if="showSettings" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4 backdrop-blur-sm" @click.self="showSettings = false"><form class="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl" @submit.prevent="saveProject"><div class="flex items-center justify-between"><h3 class="text-lg font-bold text-slate-900">Project settings</h3><button type="button" class="text-slate-400" @click="showSettings = false">✕</button></div><div class="mt-6 space-y-4"><label class="grid gap-1.5 text-sm font-semibold">Project name<input v-model="projectForm.name" required class="rounded-xl border-slate-300" /></label><InputError :message="projectForm.errors.name" /><label class="grid gap-1.5 text-sm font-semibold">Project key<input v-model="projectForm.key" required class="rounded-xl border-slate-300 uppercase" /></label><InputError :message="projectForm.errors.key" /><label class="grid gap-1.5 text-sm font-semibold">Description<textarea v-model="projectForm.description" class="rounded-xl border-slate-300" rows="4" /></label></div><div class="mt-6 flex items-center justify-between"><button type="button" class="text-sm font-semibold text-rose-600 hover:text-rose-800" @click="showDeleteProject = true">Delete project</button><div class="flex gap-2"><button type="button" class="rounded-lg px-4 py-2 text-sm font-semibold text-slate-500" @click="showSettings = false">Cancel</button><SubmitButton :loading="projectForm.processing" loading-text="Saving…">Save project</SubmitButton></div></div>
                    <div v-if="project.members.length > 1" class="mt-6 border-t border-slate-100 pt-5"><h4 class="text-sm font-bold text-slate-800">Team members</h4><div class="mt-3 space-y-2"><div v-for="member in project.members.filter((item) => item.id !== project.owner.id)" :key="member.id" class="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2"><div><p class="text-sm font-semibold text-slate-700">{{ member.name }}</p><p class="text-xs text-slate-400">{{ member.email }} · {{ member.role }}</p></div><button type="button" :disabled="removingMember !== null" class="inline-flex items-center gap-1.5 text-xs font-semibold text-rose-600 disabled:opacity-50" @click="removeMember(member)"><LoadingSpinner v-if="removingMember === member.id" size="xs" label="Removing member" />{{ removingMember === member.id ? 'Removing…' : 'Remove' }}</button></div></div></div>
                </form></div>

        <div v-if="showDeleteProject" class="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-4"><div class="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div class="grid h-11 w-11 place-items-center rounded-full bg-rose-100 font-bold text-rose-600">!</div><h3 class="mt-4 text-lg font-bold text-slate-900">Delete this project?</h3><p class="mt-2 text-sm leading-6 text-slate-500">This permanently removes the project, all tasks, and activity history. This action cannot be undone.</p><div class="mt-6 flex justify-end gap-2"><button type="button" class="rounded-lg px-4 py-2 text-sm font-semibold text-slate-500" @click="showDeleteProject = false">Cancel</button><SubmitButton type="button" variant="danger" :loading="projectForm.processing" loading-text="Deleting…" @click="deleteProject">Delete permanently</SubmitButton></div></div></div>
    </AuthenticatedLayout>
</template>
